    {"source_id":"tr_3d17_0004d05f","decision":"used","reason":"demonstrates success of pre-planned task assignment with clear written responsibilities","orientation_ids":["O1"]},
    {"source_id":"tr_3d17_0004d05d","decision":"used","reason":"shows failure from unplanned changes and missing accountability","orientation_ids":["O2"]}
  ],
  "orientations": [
    {"id":"O1","criterion":"assign each person a fixed, written responsibility before the first meeting","consequence":"prevents last-minute changes and missing materials by creating clear accountability","limit":"when the skill requires spontaneous adaptation or when participants cannot commit in advance","source_ids":["tr_3d17_0004d05f"],"evidence":[{"source_id":"tr_3d17_0004d05f","quote":"I planned the community event privately and assigned each task without discussion. The written responsibilities were clear and the event was completed on time."}]},
    {"id":"O2","criterion":"create mutual accountability checkpoints during the session itself","consequence":"replaces missing external resources with peer monitoring and immediate correction","limit":"when trust among participants is very low or when time pressure prevents mid-session review","source_ids":["tr_3d17_0004d05d"],"evidence":[{"source_id":"tr_3d17_0004d05d","quote":"When we divided a small fund through shared discussion, several promises were changed without notice and the materials never arrived."}]}
  ],
  "candidates": [
    {
      "id":"A",
      "kind":"direct",
      "mechanism":"pre-planned written task assignment plus peer checkpoints",
      "answer":"Each adult receives a numbered index card with one micro-skill (e.g., knot, measurement, safety check) and the exact order of teaching. In hour one, card-holders teach their micro-skill to three rotating partners for twelve minutes each. In hour two, trios recombine into one working model that must pass a five-point checklist posted on the wall. Success is the completed model plus signed checklist by every participant.",
      "orientation_ids":["O1","O2"],
      "source_ids":["tr_3d17_0004d05f","tr_3d17_0004d05d"]
    },
    {
      "id":"B",
      "kind":"oriented",
      "mechanism":"pre-planned written task assignment plus peer checkpoints",
      "answer":"Assign each participant a fixed index-card responsibility before arrival. Hour one: teach your item to three others in twelve-minute rounds. Hour two: trios assemble one testable product and mark a visible five-point checklist. Observable success is the finished product and every signature confirming checklist items.",
      "orientation_ids":["O1","O2"],
      "source_ids":["tr_3d17_0004d05f","tr_3d17_0004d05d"]
    },
    {
      "id":"C",
      "kind":"exploratory",
      "mechanism":"chain-of-expertise where each learner invents a one-minute demonstration",
      "answer":"Learners sit in a circle. Person 1 invents a one-minute demonstration of any relevant micro-skill and teaches the neighbor; that neighbor must then teach it plus one new micro-skill to the next person within one minute. The chain continues until every participant has both taught and learned twelve distinct micro-skills. Observable success is each person correctly reproducing the entire chain in under two minutes.",
      "orientation_ids":[],
      "source_ids":[]
    }
  ]
}

